  const testResults=[];
  const assert=(name,ok,detail='')=>testResults.push(`${ok?'PASS':'FAIL'} ${name}${detail?': '+detail:''}`);
  try {
    assert('distance condition boundaries',conditionForDistance(24.99).bonus===.05&&conditionForDistance(25).bonus===.12&&conditionForDistance(49.99).bonus===.12&&conditionForDistance(50).bonus===.25);
    const base=partCatalog.find(p=>p.id==='spiked-ram');
    assert('market stats scale by tier',makeMarketPart(base,24).hullReduction===.315&&makeMarketPart(base,25).hullReduction===.336&&makeMarketPart(base,50).hullReduction===.375);
    assert('initial market cadence',nextMarket===25);
    assert('all six van slots preserved',Object.keys(rig).length===6&&['Engine','Roof','Front Utility','Back Utility','Wheels','Interior'].every(k=>k in rig));
    assert('crew skills preserved',crew.length===3&&crew.every(m=>m.skillUses===2&&m.positiveTrait&&m.negativeTrait));
    assert('road encounters do not award Scrap',events.every(e=>[...e.choices,...(e.specials||[])].every(c=>!Object.hasOwn(c.delta,'scrap'))));
    const originalRandom=Math.random;Math.random=()=>.99;
    dist=25;scrap=100;showMarket();
    assert('market at 25 miles shows Worn stock',marketStock.length===3&&marketStock.every(p=>p.tier==='worn')&&$('marketCondition').textContent.includes('WORN +12% EFFECT'));
    assert('market advances cadence by 25 miles',nextMarket===50);
    const firstPart=marketStock[0];buyPart(firstPart.id);
    assert('purchased part equips without dropping slots',rig[firstPart.slot]?.id===firstPart.id&&Object.keys(rig).length===6);
    $('leaveMarket').click();
    const beforeFood=food;startScavenge();scavengeHits=3;scavengeActive=false;scavengeFinished=true;returnFromScavenge();
    assert('Scavenge costs rations and awards Scrap',scrap===6&&food===beforeFood+1,`scrap=${scrap}, food delta=${food-beforeFood}`);
    const beforeLog=$('logFeed').children.length;emitRoadFlavor();
    assert('Road Log flavor appends without pausing',!paused&&$('logFeed').children.length===Math.min(4,beforeLog+1));
    Math.random=()=>.4;const oldMorale=morale;emitRoadFlavor();
    assert('minor friction can lower morale without pausing',!paused&&morale===oldMorale-1);
    Math.random=originalRandom;
  } catch(e) { testResults.push('FAIL runtime exception: '+e.stack); }
  const output=document.createElement('pre');output.id='test-results';output.textContent=testResults.join('\\n');document.body.append(output);
  '''
src=src.replace(needle,needle+checks)
