   function canUseSkill(member){if(member.health<=0||member.skillUses<=0||ended||(paused&&!camping))return false;if(member.positiveTrait==='Tinkerer')return health<100;if(member.positiveTrait==='Medic')return crew.some(person=>person.health>0&&person.health<100);return true}
   function activateSkill(member){if(!canUseSkill(member))return;member.skillUses--;let message='';if(member.positiveTrait==='Tinkerer'){health=Math.min(100,health+20);message=`${member.name} repaired the hull (+20).`}else if(member.positiveTrait==='Medic'){const target=crew.filter(person=>person.health>0&&person.health<100).sort((a,b)=>a.health-b.health)[0];if(!target){member.skillUses++;return}target.health=Math.min(100,target.health+30);message=`${member.name} treated ${target.name} (+30 vitals).`}else if(member.positiveTrait==='Scavenger'){addScrap(14);message=`${member.name} salvaged a cache (+${Math.round(14*scrapMultiplier())} scrap).`}else{nextEvent+=12;message=`${member.name} cleared the road ahead. Next encounter delayed.`}$('logText').textContent=message;showToast(message);updateUI()}
   function updateCrew(){let active=0;$('crewList').innerHTML=crew.map(member=>{const state=crewState(member);if(state!=='dead')active++;const label=state==='dead'?'DOWN':state==='fit'?'FIT':state==='wounded'?'WOUNDED':'CRITICAL';return `<div class="crew-member ${state}" aria-label="${member.name}, ${label}, ${Math.round(member.health)} percent, ${member.positiveTrait}, ${member.negativeTrait}"><div class="crew-avatar">${member.initial}</div><div class="crew-info"><div class="crew-top"><span class="crew-name">${member.name}</span><span class="crew-status">${label}</span></div><div class="trait-tags"><span class="trait-tag positive">${member.positiveTrait}</span><span class="trait-tag negative">${member.negativeTrait}</span></div><div class="crew-bar"><span style="width:${Math.max(0,member.health)}%"></span></div><button class="crew-skill" type="button" ${canUseSkill(member)?'':'disabled'}><span>${skillName(member)}</span><small>${member.skillUses}/2 USES</small></button></div></div>`}).join('');$('crewList').querySelectorAll('.crew-skill').forEach((button,index)=>button.onclick=()=>activateSkill(crew[index]));$('crewCount').textContent=`${active} / 3 ACTIVE`}
   function renderRig(){const slots=Object.entries(rig);$('rigSlots').innerHTML=slots.map(([slot,part])=>`<div class="rig-slot ${part?'equipped':''}"><span>${slot.toUpperCase()}</span><strong>${part?part.name:'EMPTY'}</strong>${part?`<small>${part.short}</small>`:''}</div>`).join('')}
