const { spawn } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');
const profile = fs.mkdtempSync('/tmp/opencode/chrome-');
const chrome = spawn('chromium', ['--headless', '--no-sandbox', '--disable-gpu', '--remote-debugging-port=9222', `--user-data-dir=${profile}`, 'about:blank'], { stdio: 'ignore' });
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  try {
    let targets;
    for (let i = 0; i < 50; i++) {
      try { targets = await (await fetch('http://127.0.0.1:9222/json')).json(); break; } catch { await sleep(100); }
    }
    const target = targets.find(item => item.type === 'page');
    const ws = new WebSocket(target.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
    let id = 0; const pending = new Map();
    ws.onmessage = event => { const msg = JSON.parse(event.data); if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); } };
    const send = (method, params = {}) => new Promise(resolve => { const current = ++id; pending.set(current, resolve); ws.send(JSON.stringify({ id: current, method, params })); });
    const evalJS = async expression => {
      const response = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
      if (response.error || response.result.exceptionDetails) throw new Error(JSON.stringify(response.error || response.result.exceptionDetails));
      return response.result.result.value;
    };
    await send('Page.enable'); await send('Runtime.enable');
    await send('Page.addScriptToEvaluateOnNewDocument', { source: 'window.__fakeNow=0; window.__rafQueue=[]; Object.defineProperty(performance,"now",{value:()=>window.__fakeNow}); window.requestAnimationFrame=cb=>{window.__rafQueue.push(cb);return window.__rafQueue.length};' });
    await send('Page.navigate', { url: 'file:///home/runner/work/PlayGround/PlayGround/index.html' });
    for (let i = 0; i < 40; i++) { try { if (await evalJS('!!document.querySelector("#crewList .stress-bar")')) break; } catch {} await sleep(100); }
    const checks = [];
    checks.push(['initial stress bars', await evalJS('document.querySelectorAll("#crewList .stress-bar").length===3')]);
    await evalJS('window.__fakeNow+=100; window.__rafQueue.shift()?.(window.__fakeNow)');
    checks.push(['driving raises stress', await evalJS('Number(document.querySelector(".stress-row strong").textContent.replace("%",""))>0')]);
    let eventOpened = false;
    for (let i = 0; i < 380; i++) {
      const state = await evalJS('({q:document.querySelectorAll("#choices .choice").length,m:document.querySelector("#marketShade").classList.contains("show"),e:document.querySelector("#eventShade").classList.contains("show"),d:parseFloat(document.querySelector("#distance").textContent)})');
      if (state.e) {
        eventOpened = true;
        checks.push(['event choices render and badges', await evalJS('document.querySelectorAll("#choices .choice").length>=2 && (document.querySelectorAll(".attitude-badge").length>0)')]);
        await evalJS('document.querySelector("#choices .choice").click()');
        continue;
      }
      if (state.m) break;
      await evalJS('window.__fakeNow+=100; window.__rafQueue.shift()?.(window.__fakeNow)');
    }
    checks.push(['event occurred', eventOpened]);
    const atMarket = await evalJS('document.querySelector("#marketShade").classList.contains("show")');
    checks.push(['market stop at 50 miles', atMarket && Number(await evalJS('document.querySelector("#distance").textContent'))>=50]);
    if (atMarket) await evalJS('document.querySelector("#leaveMarket").click()');
    const before = await evalJS('[...document.querySelectorAll(".stress-row strong")].map(n=>Number(n.textContent.replace("%","")))');
    await evalJS('document.querySelector("#campButton").click()');
    const after = await evalJS('[...document.querySelectorAll(".stress-row strong")].map(n=>Number(n.textContent.replace("%","")))');
    checks.push(['camp pauses, spends rations, restores skills', await evalJS('document.querySelector("#status").textContent.includes("CAMPED") && document.querySelectorAll(".crew-skill").length===3')]);
    checks.push(['camp lowers stress', after.every((value,index)=>value<=before[index] && (before[index]===0 || value<before[index]))]);
    console.log(JSON.stringify(checks, null, 2));
    if (checks.some(([, pass]) => !pass)) process.exitCode = 1;
    ws.close();
  } finally { chrome.kill('SIGTERM'); }
})().catch(error => { console.error(error); chrome.kill('SIGTERM'); process.exitCode = 1; });

